import React, { useEffect, useState } from "react";
import {useNavigate} from "react-router-dom";
import {User} from "lucide-react";

function ReviewerIndexPage() {
    const [username, setUsername] = useState("");
    const [userId, setUserId] = useState(null);
    const [joinedStudies, setJoinedStudies] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const navigate = useNavigate();

    const [pendingStudies, setPendingStudies] = useState([]);
    const [rejectingStudyId, setRejectingStudyId] = useState(null);
    const [rejectionReason, setRejectionReason] = useState("");

    // Function to get time-based greeting
    const getGreeting = () => {
        const hour = new Date().getHours();

        if (hour >= 5 && hour < 12) {
            return "Good morning";
        } else if (hour >= 12 && hour < 17) {
            return "Good afternoon";
        } else if (hour >= 17 && hour < 22) {
            return "Good evening";
        } else {
            return "Good night";
        }
    };

    const joinStudyAndAction = async (studyId, actionCallback) => {
        if (!userId) return;
        try {
            const token = localStorage.getItem("token");

            const joinRes = await fetch(`http://localhost:8080/api/reviewers/${userId}/join-study/${studyId}`, {
                method: "POST",
                headers: { "Authorization": `Bearer ${token}` }
            });
            if (joinRes.ok || joinRes.status === 400) {
                const studyToAdd = pendingStudies.find(s => s.id === studyId);
                if (studyToAdd && !joinedStudies.some(s => s.id === studyId)) {
                    setJoinedStudies(prev => [...prev, studyToAdd]);
                }

                if (actionCallback) await actionCallback();
            }
        } catch (err) {
            console.error("Error joining study:", err);
        }
    };

    const handleRejectClick = (studyId) => {
        setRejectingStudyId(studyId);
        setRejectionReason("");
    };

    const handleCancelReject = () => {
        setRejectingStudyId(null);
        setRejectionReason("");
    };

    const handleRejectSubmit = async () => {
        if (!rejectionReason.trim()) {
            alert("Please provide a reason for rejection.");
            return;
        }
        await joinStudyAndAction(rejectingStudyId, async () => {
            try {
                const token = localStorage.getItem("token");
                const res = await fetch(`http://localhost:8080/api/studies/${rejectingStudyId}/reject`, {
                    method: "PATCH",
                    headers: {
                        "Authorization": `Bearer ${token}`,
                        "Content-Type": "application/json"
                    },
                    body: JSON.stringify({ reason: rejectionReason })
                });

                if (res.ok) {
                    const study = pendingStudies.find(s => s.id === rejectingStudyId);
                    alert(`Study "${study?.title}" has been rejected.`);

                    setPendingStudies(prev => prev.filter(s => s.id !== rejectingStudyId));
                    handleCancelReject();
                } else {
                    alert("Failed to reject study.");
                }
            } catch (err) {
                console.error("Error rejecting study:", err);
            }
        });
    };

    useEffect(() => {
        const fetchApproval = async () => {
            try {
                const token = localStorage.getItem("token");
                const res = await fetch("http://localhost:8080/api/studies/waiting-for-approval", {
                    headers: { Authorization: `Bearer ${token}` }
                });

                if (res.ok) {
                    const data = await res.json();
                    setPendingStudies(data);
                }
            } catch (err) {
                console.error("Failed to fetch approval:", err);
            }
        };

        fetchApproval();
    }, []);

    useEffect(() => {
        const storedUser = JSON.parse(localStorage.getItem("user"));
        if (storedUser && storedUser.username) {
            setUsername(storedUser.username);
            setUserId(storedUser.id);
        } else {
            navigate("/");
        }
    }, [navigate]);

    useEffect(() => {
        if (!userId) return;
        const fetchJoinedStudies = async () => {
            try {
                const token = localStorage.getItem("token");
                const res = await fetch(`http://localhost:8080/api/reviewers/${userId}/joined-studies`, {
                    headers: { Authorization: `Bearer ${token}` }
                });
                if (res.ok){
                    const data = await res.json();
                    setJoinedStudies(data);
                }
            } catch (err) {
                console.error("Failed to fetch joined studies:", err);
            } finally {
                setIsLoading(false);
            }
        };
        fetchJoinedStudies();
    }, [userId]);

    const handleLogout = () => {
        localStorage.removeItem("token");
        localStorage.removeItem("user");
        navigate("/");
    };

    const handleProfile = () => {
        navigate("/profile");
    };

    const handleNotifications = () => {
        alert("Notification Center - Coming Soon!");
    };

    const handleReviewResearch = async (studyId) => {
        await joinStudyAndAction(studyId, async () => {
            alert(`You have joined Study ID: ${studyId} as a reviewer. Opening details...`);
        });
    };

    const handleApproveStudy = async (studyId) => {
        await joinStudyAndAction(studyId, async () => {
            try {
                const token = localStorage.getItem("token");
                const res = await fetch(`http://localhost:8080/api/studies/${studyId}/approve`, {
                    method: "PATCH",
                    headers: { "Authorization": `Bearer ${token}` }
                });

                if (res.ok) {
                    const study = pendingStudies.find(s => s.id === studyId);
                    alert(`Study "${study?.title}" has been approved!`);
                    setPendingStudies(prev => prev.filter(s => s.id !== studyId));
                } else {
                    alert("Failed to approve study.");
                }
            } catch (err) {
                console.error("Error:", err);
            }
        });
    };

    const handleReportStudy = async (studyId) => {
        await joinStudyAndAction(studyId, async () => {
            try {
                const token = localStorage.getItem("token");
                const res = await fetch(`http://localhost:8080/api/studies/${studyId}/report`, {
                    method: "PATCH",
                    headers: { "Authorization": `Bearer ${token}` }
                });

                if (res.ok) {
                    const study = pendingStudies.find(s => s.id === studyId);
                    alert(`Study "${study?.title}" has been reported.`);
                    setPendingStudies(prev => prev.filter(s => s.id !== studyId));
                } else {
                    alert("Failed to report study.");
                }
            } catch (err) {
                console.error("Error:", err);
            }
        });
    };

    const handleStudyClick = (study) => {
        alert(`Opening details for: ${study.title}\nStatus: ${study.status}\nParticipants: ${study.participants ? study.participants.length : 0}`);
    };

    useEffect(() => {
        document.body.style.margin = "0";
        document.body.style.padding = "0";
        document.body.style.overflowY = "auto";
        document.body.style.overflowX = "hidden";

        const styleSheet = document.createElement("style");
        styleSheet.textContent = `
            @keyframes float { 
                0%, 100% { transform: translateY(0px); } 
                50% { transform: translateY(-20px); } 
            }
            @keyframes floatParticle {
                0% { transform: translateY(0); opacity: 0.4; }
                50% { opacity: 1; }
                100% { transform: translateY(-120vh); opacity: 0; }
            }
            @keyframes pulse { 
                0%, 100% { opacity: 0.5; } 
                50% { opacity: 0.8; } 
            }
            .nav-button:hover, .logout-button:hover, .reject-button:hover, 
            .action-button:hover, .approve-button:hover, .report-button:hover {
                transform: translateY(-2px) !important;
            }
            .study-card:hover {
                transform: translateY(-4px) !important;
                box-shadow: 0 8px 24px rgba(96, 165, 250, 0.3) !important;
                border-color: rgba(96, 165, 250, 0.5) !important;
            }
            .logout-button:hover {
                transform: scale(1.06) !important;
                box-shadow: 0 0 18px rgba(239,68,68,0.7) !important;
                border-color: rgba(239,68,68,0.85) !important;
            }
        `;
        document.head.appendChild(styleSheet);
        return () => document.head.removeChild(styleSheet);
    }, []);

    const getStatusColor = (status) => {
        switch(status) {
            case "published": return { bg: "rgba(34, 197, 94, 0.2)", color: "#22c55e" };
            case "in-progress": return { bg: "rgba(96, 165, 250, 0.2)", color: "#60a5fa" };
            case "draft": return { bg: "rgba(156, 163, 175, 0.2)", color: "#9ca3af" };
            default: return { bg: "rgba(251, 146, 60, 0.2)", color: "#fb923c" };
        }
    };

    return (
        <div style={styles.container}>
            {/* Particles */}
            <div style={styles.particles}>
                {[...Array(55)].map((_, i) => {
                    const startY = Math.random() * 100;
                    const negDelay = -(Math.random() * 15).toFixed(2);

                    return (
                        <div
                            key={i}
                            style={{
                                ...styles.particle,
                                left: `${Math.random() * 100}%`,
                                top: `${startY}vh`,
                                animationDelay: `${negDelay}s`,
                                animationDuration: `${16 + Math.random() * 10}s`,
                                opacity: 0.45,
                            }}
                        />
                    );
                })}
            </div>

            <div style={styles.navbar}>
                <div style={styles.navLeft}>
                    <span style={styles.welcomeText}>Reviewer Dashboard</span>
                </div>
                <div style={styles.navRight}>
                    <span style={styles.userText}>{username}</span>
                    <button className="nav-button" style={styles.notificationButton} onClick={handleNotifications}>
                        Notification Center
                    </button>
                    <button style={styles.profileBtn} onClick={handleProfile}>
                        <User size={16} />
                        My Profile
                    </button>
                    <button className="logout-button" style={styles.logoutButton} onClick={handleLogout}>
                        Logout
                    </button>
                </div>
            </div>

            <div style={styles.mainContent}>
                <div style={styles.contentCard}>
                    <div style={styles.headerSection}>
                        <h1 style={styles.heroTitle}>{getGreeting()}, {username}!</h1>
                        <p style={styles.heroSubtitle}>
                            Review and approve research studies to maintain quality standards.
                        </p>
                    </div>

                    <div style={styles.centerContent}>
                        {/* Approve Study Block */}
                        <div style={styles.sectionBlock}>
                            <h3 style={styles.sectionTitle}>Approve Study Publication</h3>
                            {pendingStudies.length === 0 ? (
                                <div style={styles.emptyState}>
                                    <p style={styles.emptyText}>No studies pending approval at this time.</p>
                                </div>
                            ) : (
                                <div style={styles.listContainer}>
                                    {pendingStudies.map((study) => (
                                        <div key={study.id} style={styles.approvalItem}>
                                            <div style={styles.studyHeader}>
                                                <div style={styles.studyMainInfo}>
                                                    <span style={styles.studyName}>{study.title}</span>
                                                    <div style={styles.studyMeta}>
                                                        <span style={styles.metaText}>Author: {study.researcher ? `${study.researcher.name} ${study.researcher.lastname}` : "Unknown"}</span>
                                                        <span style={styles.metaText}>•</span>
                                                        <span style={styles.metaText}>Submitted: {study.updatedAt ? new Date(study.updatedAt).toLocaleDateString() : "N/A"}</span>
                                                    </div>
                                                </div>
                                                <span style={{ ...styles.statusBadge, background: "rgba(251, 146, 60, 0.2)", color: "#fb923c" }}>
                                                    {study.publishStatus || study.status}
                                                </span>
                                            </div>
                                            <div style={styles.actionButtons}>
                                                <button className="action-button" style={styles.reviewButton} onClick={() => handleReviewResearch(study.id)}>
                                                    Review Research
                                                </button>
                                                <button className="approve-button" style={styles.approveButton} onClick={() => handleApproveStudy(study.id)}>
                                                    Approve Study
                                                </button>
                                                <button className="reject-button" style={styles.rejectButton} onClick={() => handleRejectClick(study.id)}>
                                                    Reject Study
                                                </button>
                                                <button className="report-button" style={styles.reportButton} onClick={() => handleReportStudy(study.id)}>
                                                    Report for Admin Review
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>

                        {/* My Studies Block */}
                        <div style={styles.sectionBlock}>
                            <h3 style={styles.sectionTitle}>My Studies</h3>
                            {isLoading ? (
                                <div style={styles.loadingContainer}>
                                    <div style={styles.spinner}></div>
                                    <p style={styles.loadingText}>Loading studies...</p>
                                </div>
                            ) : joinedStudies.length === 0 ? (
                                <div style={styles.emptyState}>
                                    <p style={styles.emptyText}>You haven't joined any studies yet.</p>
                                </div>
                            ) : (
                                <div style={styles.studiesGrid}>
                                    {joinedStudies.map((study) => {
                                        const statusColors = getStatusColor(study.status);
                                        return (
                                            <div key={study.id} className="study-card" style={styles.studyCard} onClick={() => handleStudyClick(study)}>
                                                <div style={styles.cardHeader}>
                                                    <h4 style={styles.cardTitle}>{study.title}</h4>
                                                    <span style={{ ...styles.statusBadge, background: statusColors.bg, color: statusColors.color }}>
                                                        {study.status}
                                                    </span>
                                                </div>
                                                <div style={styles.cardBody}>
                                                    <div style={styles.cardStat}>
                                                        <span style={styles.statLabel}>Participants</span>
                                                        <span style={styles.statValue}>{study.participants ? study.participants.length : 0}</span>
                                                    </div>
                                                    <div style={styles.cardStat}>
                                                        <span style={styles.statLabel}>Last Updated</span>
                                                        <span style={styles.statValue}>{study.updatedAt ? new Date(study.updatedAt).toLocaleDateString() : "N/A"}</span>
                                                    </div>
                                                </div>
                                                <div style={styles.cardFooter}>
                                                    <span style={styles.clickHint}>Click for details →</span>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {rejectingStudyId && (
                <div style={styles.modalOverlay}>
                    <div style={styles.modalContent}>
                        <h3 style={styles.modalTitle}>Reject Study Publication</h3>
                        <p style={styles.modalText}>Please explain the reason for rejection.</p>
                        <textarea style={styles.modalTextarea} value={rejectionReason} onChange={(e) => setRejectionReason(e.target.value)} placeholder="Type rejection reason here..." rows={4} />
                        <div style={styles.modalActions}>
                            <button style={styles.cancelButton} onClick={handleCancelReject}>Cancel</button>
                            <button style={styles.submitRejectButton} onClick={handleRejectSubmit}>Submit Rejection</button>
                        </div>
                    </div>
                </div>
            )}

            <footer style={styles.footer}>
                <p style={styles.footerText}>© {new Date().getFullYear()} Artifact Comparator — Reviewer Panel</p>
            </footer>

            <style>{`
                @keyframes spin {
                    to { transform: rotate(360deg); }
                }
            `}</style>
        </div>
    );
}

